// Package rewrite is the Rust port of `traffic/rewrite/`, generated by rust-anything: the same API, each
// function calling the Rust library. Regenerate with `rust-anything refresh`.
package rewrite

/*
#cgo LDFLAGS: -L${SRCDIR}/../target/release -lrewrite_rs -Wl,-rpath,${SRCDIR}/../target/release
#include <stdbool.h>
#include <stdint.h>
#include <stdlib.h>
char *rust_anything_call(const char *name, const char *args);
void rust_anything_free(char *ptr);
*/
import "C"

import (
	"encoding/binary"
	"encoding/json"
	"errors"
	"math"
	"runtime"
	"unsafe"
)

var _ = binary.LittleEndian
var _ = runtime.KeepAlive

type Rule struct {
	ID       int64    `json:"id"`
	Name     string   `json:"name"`
	Enabled  bool     `json:"enabled"`
	Phase    Phase    `json:"phase"`
	Priority int      `json:"priority"`
	Matchers Matchers `json:"matchers"`
	Actions  []Action `json:"actions"`
	Note     string   `json:"note"`
}

// Phase, Matchers, Action, HeaderMatcher mirror traffic/rewrite/rule.go so the
// generated driver compiles. Validate only needs the JSON shape.
type Phase string

const (
	PhaseRequest  Phase = "request"
	PhaseResponse Phase = "response"
)

type HeaderMatcher struct {
	Name       string `json:"name"`
	ValueRegex string `json:"value_regex,omitempty"`
}

type Matchers struct {
	Methods       []string        `json:"methods,omitempty"`
	Host          string          `json:"host,omitempty"`
	URLRegex      string          `json:"url_regex,omitempty"`
	Headers       []HeaderMatcher `json:"headers,omitempty"`
	BodyRegex     string          `json:"body_regex,omitempty"`
	Status        []string        `json:"status,omitempty"`
	RespHeaders   []HeaderMatcher `json:"resp_headers,omitempty"`
	RespBodyRegex string          `json:"resp_body_regex,omitempty"`
}

type Action struct {
	Type      string `json:"type"`
	Name      string `json:"name,omitempty"`
	Regex     string `json:"regex,omitempty"`
	Value     string `json:"value,omitempty"`
	Sensitive bool   `json:"sensitive,omitempty"`
}

// rustAnythingDecode decodes JSON into target; floats may be {"$num": "NaN" | "Infinity" | ...}.
func rustAnythingDecode(raw json.RawMessage, target any) error {
	if f, ok := target.(*float64); ok && len(raw) > 0 && raw[0] == '{' {
		var marker map[string]string
		if err := json.Unmarshal(raw, &marker); err != nil {
			return err
		}
		switch marker["$num"] {
		case "NaN":
			*f = math.NaN()
		case "Infinity":
			*f = math.Inf(1)
		case "-Infinity":
			*f = math.Inf(-1)
		case "-0":
			*f = math.Copysign(0, -1)
		default:
			return errors.New("not a number")
		}
		return nil
	}
	if len(raw) == 0 {
		raw = json.RawMessage("null")
	}
	return json.Unmarshal(raw, target)
}

// rustAnythingEncode marks the floats JSON cannot carry.
func rustAnythingEncode(v any) any {
	var f float64
	switch x := v.(type) {
	case float64:
		f = x
	case float32:
		f = float64(x)
	default:
		return v
	}
	switch {
	case math.IsNaN(f):
		return map[string]string{"$num": "NaN"}
	case math.IsInf(f, 1):
		return map[string]string{"$num": "Infinity"}
	case math.IsInf(f, -1):
		return map[string]string{"$num": "-Infinity"}
	case f == 0 && math.Signbit(f):
		return map[string]string{"$num": "-0"}
	}
	return v
}

type rustAnythingAnswer struct {
	Ok    json.RawMessage `json:"ok"`
	Error *string         `json:"error"`
	Panic *string         `json:"panic"`
}

func rustAnythingCall(name string, args ...any) (json.RawMessage, error) {
	for i, a := range args {
		args[i] = rustAnythingEncode(a)
	}
	encoded, err := json.Marshal(args)
	if err != nil {
		panic(err)
	}
	cName := C.CString(name)
	defer C.free(unsafe.Pointer(cName))
	cArgs := C.CString(string(encoded))
	defer C.free(unsafe.Pointer(cArgs))
	answer := C.rust_anything_call(cName, cArgs)
	defer C.rust_anything_free(answer)
	var a rustAnythingAnswer
	if err := json.Unmarshal([]byte(C.GoString(answer)), &a); err != nil {
		panic(err)
	}
	if a.Panic != nil {
		panic(*a.Panic)
	}
	if a.Error != nil {
		return nil, errors.New(*a.Error)
	}
	return a.Ok, nil
}

func rustAnythingMust(err error) {
	if err != nil {
		panic(err)
	}
}

// Validate is the Rust port of `func Validate(r Rule) error` (`traffic/rewrite/rule.go:100`).
func Validate(raArg0 Rule) error {
	_, err := rustAnythingCall("Validate", raArg0)
	if err != nil {
		return err
	}
	return nil
}
